window.createWorkLarva=function(canvas){
let ctx=canvas.getContext('2d');
const PI=Math.PI, clamp=(v,a=0,b=1)=>Math.max(a,Math.min(b,v)),smooth=v=>{v=clamp(v);return v*v*(3-2*v)},mix=(a,b,u)=>a+(b-a)*u;
function ellipse(x,y,rx,ry,fill,stroke='',width=1,angle=0){
 ctx.beginPath();ctx.ellipse(x,y,Math.max(.01,rx),Math.max(.01,ry),angle,0,PI*2);ctx.fillStyle=fill;ctx.fill();if(stroke){ctx.lineWidth=width;ctx.strokeStyle=stroke;ctx.stroke()}
}
function gradient(x,y,r,stops){let g=ctx.createRadialGradient(x,y,0,x,y,r);for(const [k,v] of stops)g.addColorStop(k,v);return g}
const skin=(x,y,r)=>gradient(x-r*.28,y-r*.55,2*r,[[0,'#ffe0ad'],[.18,'#ff9a9d'],[.48,'#fa7888'],[.73,'#dc536d'],[.93,'#ffc389'],[1,'#a84c4f']]);
const facePaint=(x,y,r)=>gradient(x-r*.19,y-r*.48,1.9*r,[[0,'#fff3cb'],[.47,'#ffd6a9'],[.82,'#ffab93'],[1,'#e97877']]);
function bodySegment(x,y,r,angle,step,t){
 ctx.save();ctx.translate(x,y);ctx.rotate(angle);const tick=Math.sin(t*8-step*1.4);
 for(const side of [-1,1])ellipse(side*r*.43+tick*side*r*.12,r*.88+tick*side*r*.09,r*.19,r*.19,'#edab77','#a85d4e',1);
 ellipse(0,0,r*1.06,r*.93,skin(0,0,r),'#9e4748',1.5);
 ellipse(r*.26,-r*.33,r*.21,r*.33,'#ffcd5f','',1,-.38);
 ellipse(-r*.31,-r*.56,r*.23,r*.075,'#fff0ce','',1,-.18);ctx.restore()
}
const ART_DATA={"antenna": "data:image/png;base64,", "eye0": "data:image/png;base64,", "eye1": "data:image/png;base64,", "ring": "data:image/png;base64,", "skin": "data:image/png;base64,"};
const art={}, cheekCache=new Map();
for(const [name,url] of Object.entries(ART_DATA)){const img=new Image();img.src=url;art[name]=img}
function head(x,y,t,dir,full,chew,lift){
 if(!Object.values(art).every(img=>img.complete&&img.naturalWidth))return;
 ctx.save();ctx.translate(x,y-14*lift);ctx.scale(dir,1);ctx.rotate(-.22*lift+.017*Math.sin(t*5));
 ctx.translate(0,Math.sin(t*5)*1.2);ctx.scale(.47,.47);ctx.translate(-108,-94);
 ctx.save();ctx.translate(94,24);ctx.rotate(.075*Math.sin(t*5-.55)+lift*.12);ctx.drawImage(art.antenna,-18,-93,71,103);ctx.restore();
 // Only the cheek rows expand. The eyes and moustache retain their shape.
 const level=Math.round(full*32);
 if(!cheekCache.has(level)){
   const plate=document.createElement('canvas');plate.width=260;plate.height=177;
   const skinCtx=plate.getContext('2d');
   for(let y=0;y<177;y++){
     const band=Math.exp(-((y-120)**2)/1000),extra=19*(level/32)**1.25*band;
     skinCtx.drawImage(art.skin,0,y,216,1,22-extra,y,216+extra*2,1);
   }
   cheekCache.set(level,plate)
 }
 ctx.drawImage(cheekCache.get(level),-22,0);
 const blink=Math.max(lift*.70,Math.pow(Math.max(0,Math.cos((t+.7)*2.1)),110));
 for(const [key,xx,yy,w,h] of [['eye0',20,55,31,53],['eye1',111,62,43,55]]){
   let hh=h*(1-.94*blink);ctx.drawImage(art[key],xx,yy+(h-hh)*.53,w,hh)
 }
 // The illustrated moustache ring surrounds the independently animated jaw.
 ctx.save();ctx.translate(80,129-lift*3);ctx.rotate(.28);
 ellipse(0,0,32,24,'#ffce9f');
 const gape=10+chew*10+2*Math.sin(t*4)**2;
 ctx.save();ctx.beginPath();ctx.ellipse(0,3,24,gape,0,0,PI*2);ctx.clip();
 ellipse(0,3,24,gape,'#561c1a');ellipse(5,4+gape,18,gape*.60,'#f97572');ctx.restore();ctx.restore();
 ctx.drawImage(art.ring,36,88-lift*3,88,80);ctx.restore()
}
const stamp=document.createElement('canvas');stamp.width=stamp.height=128;
const paint=ctx,ink=stamp.getContext('2d');
const rest=146,count=8;
// Arc coordinates are shared by all bands, including both endpoints of a joint.
function sampler(points){
 const arcs=[0];for(let i=1;i<points.length;i++)arcs.push(arcs[i-1]+Math.hypot(points[i].x-points[i-1].x,points[i].y-points[i-1].y));
 const length=arcs.at(-1);
 function at(s){
   let l=0,h=arcs.length-1;while(h-l>1){const k=(l+h)>>1;if(arcs[k]<s)l=k;else h=k}
   const u=(s-arcs[l])/Math.max(.0001,arcs[h]-arcs[l]);return {x:mix(points[l].x,points[h].x,u),y:mix(points[l].y,points[h].y,u)}
 }
 return {at,length}
}
// Rasterize shared mesh vertices in one pass, avoiding cracks on tight turns.
const surface=document.createElement('canvas');
const gl=surface.getContext('webgl',{alpha:true,premultipliedAlpha:true,antialias:true,preserveDrawingBuffer:true});
if(!gl)throw Error('이 검수실에는 WebGL 지원 브라우저가 필요합니다.');
function shader(kind,source){
 const sh=gl.createShader(kind);gl.shaderSource(sh,source);gl.compileShader(sh);
 if(!gl.getShaderParameter(sh,gl.COMPILE_STATUS))throw Error(gl.getShaderInfoLog(sh));return sh
}
const program=gl.createProgram();
gl.attachShader(program,shader(gl.VERTEX_SHADER,'attribute vec2 pos,uv;varying vec2 tex;void main(){tex=uv;gl_Position=vec4(pos,0.,1.);}'));
gl.attachShader(program,shader(gl.FRAGMENT_SHADER,'precision mediump float;varying vec2 tex;uniform sampler2D atlas;void main(){gl_FragColor=texture2D(atlas,tex);}'));
gl.linkProgram(program);gl.useProgram(program);
const buffer=gl.createBuffer();gl.bindBuffer(gl.ARRAY_BUFFER,buffer);
for(const [attr,offset] of [['pos',0],['uv',8]]){const loc=gl.getAttribLocation(program,attr);gl.enableVertexAttribArray(loc);gl.vertexAttribPointer(loc,2,gl.FLOAT,false,16,offset)}
const texture=gl.createTexture();gl.bindTexture(gl.TEXTURE_2D,texture);
for(const [p,v] of [[gl.TEXTURE_MIN_FILTER,gl.LINEAR],[gl.TEXTURE_MAG_FILTER,gl.LINEAR],[gl.TEXTURE_WRAP_S,gl.CLAMP_TO_EDGE],[gl.TEXTURE_WRAP_T,gl.CLAMP_TO_EDGE]])gl.texParameteri(gl.TEXTURE_2D,p,v);
gl.enable(gl.BLEND);gl.blendFunc(gl.ONE,gl.ONE_MINUS_SRC_ALPHA);gl.pixelStorei(gl.UNPACK_PREMULTIPLY_ALPHA_WEBGL,true);
stamp.width=128*count;
function draw({line,time,direction=1,fullness=0,bite=0,lift=0,boluses=[],gas=-1}){
 if(!line?.length)return;
 const tip=line.at(-1),raw=line.length>1?sampler(line):null;
 // Startup traces may contain just an anchor and one head sample. Keep the
 // resting body behind the departure point until the head has travelled its length.
 let guide=line;
 if(!raw||raw.length<rest){
   const missing=rest-(raw?.length||0),first=line[0];
   guide=[{x:first.x+direction*missing,y:first.y},...line]
 }
 const {at,length}=sampler(guide),extra=Math.max(0,length-rest);
 const stretch=clamp(extra/(rest*2));
 function boundary(u){return rest*u+extra*(1.45*u-.45*u*u)}
 const vertices=[];
 if(surface.width!==canvas.width||surface.height!==canvas.height){surface.width=canvas.width;surface.height=canvas.height;}gl.viewport(0,0,surface.width,surface.height);
 const transform=paint.getTransform();
 ctx=ink;ink.clearRect(0,0,stamp.width,stamp.height);
 for(let i=0;i<count;i++)bodySegment(128*i+64,61,49,0,i,time);
 ctx=paint;
 gl.texImage2D(gl.TEXTURE_2D,0,gl.RGBA,gl.RGBA,gl.UNSIGNED_BYTE,stamp);
 for(let i=0;i<count;i++){
   const a=boundary(i/count),b=boundary((i+1)/count),u=(i+.5)/count;
   const radius=(19+12*u)*(1-stretch*(.23-.18*u));
   const overlap=Math.min(radius*.78,(b-a)*.47);
   const begin=a-(i?overlap:0),end=b+(i<count-1?overlap:0);
   const steps=Math.max(12,Math.ceil((end-begin)/3));
   const forward=at(b).x>=at(a).x;let prior;
   for(let j=0;j<=steps;j++){
     const along=j/steps,d=mix(begin,end,along),p=at(d);
     const l=at(Math.max(0,d-2)),r=at(Math.min(length,d+2));
     const dx=r.x-l.x,dy=r.y-l.y,norm=Math.hypot(dx,dy)||1;
     const nx=-dy/norm,ny=dx/norm,frac=d/length;
     const swell=boluses.reduce((v,g)=>v+(g>=0&&g<=1?10*Math.exp(-((frac-1+g)**2)/.006):0),0);
     const scale=(radius+swell)/49;
     const edge=[0,122].map(row=>{
       const h=(row-61)*scale*(forward?1:-1);
       const kick=gas>0&&gas<1?2.4*Math.sin(2*PI*gas)*(1-gas)*Math.sin(PI*clamp(frac*8)):0; const x=p.x+nx*h,y=p.y+ny*h-4*lift*frac**8-kick;
       return [(transform.a*x+transform.c*y+transform.e)*2/canvas.width-1,1-(transform.b*x+transform.d*y+transform.f)*2/canvas.height,(i*128+10+108*(forward?along:1-along))/stamp.width,row/128]
     });
     if(prior)for(const v of [prior[0],prior[1],edge[0],edge[0],prior[1],edge[1]])vertices.push(...v);
     prior=edge
   }
 }
 gl.clearColor(0,0,0,0);gl.clear(gl.COLOR_BUFFER_BIT);gl.bufferData(gl.ARRAY_BUFFER,new Float32Array(vertices),gl.DYNAMIC_DRAW);gl.drawArrays(gl.TRIANGLES,0,vertices.length/4);
 paint.save();paint.resetTransform();paint.drawImage(surface,0,0);paint.restore();
 head(tip.x,tip.y-5,time,direction,fullness,bite,lift)
}
return {draw,segmentCount:count};
};
